import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"FRITZ!Box to MQTT","text":"Home Assistant app for FRITZ!Box data","tagline":"Publish call lists, live calls, WLAN, WAN, phonebooks and FRITZ!Box status to Home Assistant through MQTT Discovery.","actions":[{"theme":"brand","text":"Installation","link":"/en/projects/fritzbox-to-mqtt/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/ugso-ha-mqtt-addons"}]},"features":[{"icon":"📞","title":"Calls and answering machines","details":"Call lists, live call monitor and answering machines AB0 to AB4 as Home Assistant entities."},{"icon":"📶","title":"WLAN and network","details":"Switches for 2.4 GHz, 5 GHz and guest WLAN plus WAN connection data, IP addresses and link status."},{"icon":"📚","title":"Phonebooks","details":"Phonebooks with selectable display and optional exclusions for individual names."},{"icon":"🧭","title":"Multiple data sources","details":"TR-064, FRITZ!Box web/Lua fallbacks and the live call monitor are combined."},{"icon":"🏠","title":"MQTT Discovery","details":"Home Assistant creates sensors and switches automatically through MQTT Discovery."},{"icon":"🛠️","title":"Troubleshooting","details":"Dedicated troubleshooting page for login, TR-064, DNS over TLS, call monitor and MQTT."}]},"headers":[],"relativePath":"en/projects/fritzbox-to-mqtt/index.md","filePath":"en/projects/fritzbox-to-mqtt/index.md","lastUpdated":1792851046000}'),i={name:"en/projects/fritzbox-to-mqtt/index.md"};function l(n,e,r,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>FRITZ!Box to MQTT is a Home Assistant app that publishes FRITZ!Box data to Home Assistant through MQTT Discovery.</p><p>The current published add-on state lives in the shared <code>rockbaer2007/ugso-ha-mqtt-addons</code> repository. The older standalone <code>rockbaer2007/fritzbox-to-mqtt</code> repository is archived.</p><p>The app combines several data sources because FRITZ!Box models and FRITZ!OS versions do not expose every value in the same place:</p><ul><li>TR-064 for many FRITZ!Box services</li><li>FRITZ!Box web/Lua queries as fallbacks</li><li>the live call monitor on port <code>1012</code></li><li>MQTT Discovery for automatic Home Assistant entity creation</li></ul><div class="info custom-block"><p class="custom-block-title">HACS</p><p>This project is a Home Assistant Supervisor app. HACS installs custom integrations and frontend cards, but not Docker-based Supervisor apps. Install it through the Home Assistant app repository flow.</p></div><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./configuration">Configuration</a></li><li><a href="./entities">Entities</a></li><li><a href="./examples">Examples</a></li><li><a href="./troubleshooting">Troubleshooting</a></li></ul>',8)])])}const m=t(i,[["render",l]]);export{u as __pageData,m as default};
